// Detecta ubicacion sin depender de messageType (mas robusto para mensajes reales)
const body = $input.item.json.body || {};
const data = body.location || {};

// desempaquetar mensajes enviados desde dispositivos vinculados
// const m = (data.message && data.message.deviceSentMessage && data.message.deviceSentMessage.message)
//           || data.message || {};

// const live = m.liveLocationMessage || null;
// const stat = m.locationMessage || null;
// const loc  = live || stat;

if (!data) { return { esUbicacion: false }; }

const lat = data.latitude;
const lng = data.longitude;
const cliente = body.remitente_id;
const mapsUrl = `https://www.google.com/maps?q=${lat},${lng}`;
const tipoTxt = data.live ? 'su ubicacion EN TIEMPO REAL' : 'su ubicacion';
const extra = null;

const contenido = (`📍 El cliente compartio ${tipoTxt}. ` +
  (extra ? extra + '. ' : '') +
  `Coordenadas: ${lat}, ${lng}. Ver en el mapa: ${mapsUrl}`)
  .replace(/\n/g, ' ').replace(/\r/g, ' ').replace(/\t/g, ' ');

return {
  esUbicacion: true,
  enVivo: !!data.live,
  lat, lng, cliente, mapsUrl, contenido,
  keyId: (data.key && data.key.id) || null,
  secuencia: data.live ? (data.live.sequenceNumber || null) : null
};

// Construye el texto con municipio y departamento a partir de la geocodificacion
const n = $('Normalizar ubicacion1').item.json;
const g = $json || {};
const addr = (g && g.address) || {};

const departamento = addr.state || '';
const municipio = addr.municipality || addr.city || addr.town || addr.county || addr.village || addr.suburb || '';
const display = g.display_name || '';

const lugar = [municipio, departamento].filter(Boolean).join(', ');
const tipoTxt = n.enVivo ? 'su ubicacion EN TIEMPO REAL' : 'su ubicacion ACTUAL';

const contenido = (`📍 El cliente compartio ${tipoTxt}. ` +
  (lugar ? `Lugar: ${lugar}. ` : '') +
  (display ? `Direccion aprox.: ${display}. ` : '') +
  `Coordenadas: ${n.lat}, ${n.lng}. Ver en el mapa: ${n.mapsUrl}`)
  .replace(/\n/g, ' ').replace(/\r/g, ' ').replace(/\t/g, ' ');

return {
  cliente: n.cliente, lat: n.lat, lng: n.lng, enVivo: n.enVivo,
  mapsUrl: n.mapsUrl, departamento, municipio, contenido
};

