// Obtener los inputs del nodo anterior

const conversationsInput = $input.first().json.data.payload; // conversaciones

const availableAgents = $('Code').first().json.availableAgents; // array directamente

// Inicializamos el resultado
const result = [];

for (const agent of availableAgents) {
  const agentId = agent.id;

  // Filtramos las conversaciones asignadas a este agente
  const assignedConversations = conversationsInput.filter(conv => {
    return conv.meta?.assignee?.id === agentId;
  });

  result.push({
    agentId,
    assignedConversations: assignedConversations.length
  });
}

// Encontrar el agente con menos conversaciones asignadas
let minAssigned = result[0];

for (const agent of result) {
  if (agent.assignedConversations < minAssigned.assignedConversations) {
    minAssigned = agent;
  }
}

// Retornar solo ese agente
return [
  {
    json: minAssigned
  }
];

let agentsFound = false;
let availableAgents = [];

// Recorremos el array de agentes
let array = $input.all()[0].json.payload;
for (const agent of array) {
  if (agent.availability_status === 'online') {
  //if (true) {

    agentsFound = true;
    availableAgents.push(agent);
  }
}

// Devolver un solo item con los resultados
return [
  {
    json: {
      agentsFound,
      availableAgents,
    }
  }
];

